RANK = {"urgent": 0, "high": 1, "normal": 2, "low": 3}

def triage_order(tickets):
    ordered = sorted(tickets, key=lambda t: (RANK[t["priority"]], t["opened"], t["id"]))
    return [ticket["id"] for ticket in ordered]
